window.ScripturaLexicons.BDAG_PART_0185 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-01\" data-source=\"BDAG\" data-search=\"καλοδιδάσκαλος, ον adjetivo que ensina o bem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καλοδιδάσκαλος, ον</td><td>adjetivo</td><td>que ensina o bem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-02\" data-source=\"BDAG\" data-search=\"Καλοὶ λιμένες, Καλῶν λιμένων, οἱ topônimo plural Bons Portos, baía de Creta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Καλοὶ λιμένες, Καλῶν λιμένων, οἱ</td><td>topônimo plural</td><td>Bons Portos, baía de Creta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-03\" data-source=\"BDAG\" data-search=\"καλοκἀγαθία, ας, ἡ substantivo feminino nobreza de caráter; excelência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καλοκἀγαθία, ας, ἡ</td><td>substantivo feminino</td><td>nobreza de caráter; excelência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-04\" data-source=\"BDAG\" data-search=\"καλοποιέω verbo fazer o bem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καλοποιέω</td><td>verbo</td><td>fazer o bem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-05\" data-source=\"BDAG\" data-search=\"καλός, ή, όν adjetivo belo, bom, virtuoso; útil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καλός, ή, όν</td><td>adjetivo</td><td>belo, bom, virtuoso; útil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-06\" data-source=\"BDAG\" data-search=\"κάλπις, ιδος, ἡ substantivo feminino jarro; cântaro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάλπις, ιδος, ἡ</td><td>substantivo feminino</td><td>jarro; cântaro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-07\" data-source=\"BDAG\" data-search=\"κάλυμμα, ατος, τό substantivo neutro véu; cobertura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάλυμμα, ατος, τό</td><td>substantivo neutro</td><td>véu; cobertura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-08\" data-source=\"BDAG\" data-search=\"καλύπτω verbo cobrir; esconder; ocultar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καλύπτω</td><td>verbo</td><td>cobrir; esconder; ocultar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-09\" data-source=\"BDAG\" data-search=\"καλῶς advérbio bem; adequadamente; corretamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καλῶς</td><td>advérbio</td><td>bem; adequadamente; corretamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-10\" data-source=\"BDAG\" data-search=\"καμάρα, ας, ἡ substantivo feminino arco; abóbada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καμάρα, ας, ἡ</td><td>substantivo feminino</td><td>arco; abóbada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-11\" data-source=\"BDAG\" data-search=\"κἀμέ remissão lexical veja κἀγώ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κἀμέ</td><td>remissão lexical</td><td>veja κἀγώ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-12\" data-source=\"BDAG\" data-search=\"κάμηλος, ου, ὁ substantivo masculino e feminino camelo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάμηλος, ου, ὁ</td><td>substantivo masculino e feminino</td><td>camelo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-13\" data-source=\"BDAG\" data-search=\"κάμιλος, ου, ὁ substantivo masculino corda; cabo de navio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάμιλος, ου, ὁ</td><td>substantivo masculino</td><td>corda; cabo de navio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-14\" data-source=\"BDAG\" data-search=\"κάμινος, ου, ἡ substantivo feminino forno; fornalha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάμινος, ου, ἡ</td><td>substantivo feminino</td><td>forno; fornalha</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-15\" data-source=\"BDAG\" data-search=\"καμμύω verbo fechar os olhos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καμμύω</td><td>verbo</td><td>fechar os olhos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-16\" data-source=\"BDAG\" data-search=\"κάμνω verbo cansar-se; adoecer; morrer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάμνω</td><td>verbo</td><td>cansar-se; adoecer; morrer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-17\" data-source=\"BDAG\" data-search=\"κἀμοί remissão lexical veja κἀγώ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κἀμοί</td><td>remissão lexical</td><td>veja κἀγώ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-18\" data-source=\"BDAG\" data-search=\"Καμπανός, ή, όν adjetivo gentílico campano; da Campânia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Καμπανός, ή, όν</td><td>adjetivo gentílico</td><td>campano; da Campânia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-19\" data-source=\"BDAG\" data-search=\"κάμπτω verbo curvar; dobrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάμπτω</td><td>verbo</td><td>curvar; dobrar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0185-20\" data-source=\"BDAG\" data-search=\"κἄν partícula condicional e se; mesmo que; ao menos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κἄν</td><td>partícula condicional</td><td>e se; mesmo que; ao menos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0185-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καλοδιδάσκαλος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">καλός</span>, <span class=\"greek\">διδάσκαλος</span> e <span class=\"greek\">διδάσκω</span>; não documentado em outras fontes) que ensina o que é bom, com referência às mulheres idosas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:3</a>.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καλοὶ λιμένες, Καλῶν λιμένων, οἱ</h1><div class=\"entry-meta\"><span>topônimo plural</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Bons Portos, nome de uma baía na costa meridional de Creta, perto da cidade de Laseia, não documentado em outras fontes antigas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:8</a>. Diod S 3, 44, 7 descreve um porto chamado Carmutas como <span class=\"greek\">λιμὴν κάλλιστος</span>. Em geral, <span class=\"greek\">καλός</span> ocorre com certa frequência como adjetivo aplicado a um porto apropriado: Diod S 5, 10, 1 <span class=\"greek\">λιμέσι καλοῖς</span>; 5, 13, 3. <span class=\"greek\">καλὸς λιμήν</span> designa um local costeiro do mar Negro em Arriano, Peripl. 19, 5.—Breusing 158f. Mapas em JSmith, Voyage and Shipwreck of St. Paul4 1880, 82f; HBalmer, D. Romfahrt d. Ap. Pls. 1905, 313f (bibliografia); Haenchen, comentário ao trecho; Warnecke, Romfahrt 19; Hemer, Acts 136.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καλοκἀγαθία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">καλός</span> e <span class=\"greek\">ἀγαθός</span>; quanto à crase, veja Gignac I, 324; cf. Schwyzer 427; Aristófanes, Xenofonte e outros; Diod S 1, 79; Epict. 1, 7, 8; 4, 1, 164; inscrições, papiros, 4 Macabeus, Epístola de Aristeias. Frequente em Fílon; a combinação adjetival <span class=\"greek\">καλὸς κἀγαθός</span>, no uso mais antigo, designa o «homem de perfeita distinção», com ênfase na posição social superior à classe trabalhadora em geral, como em Heródoto [1, 30, 4, ocorrência mais antiga, nas palavras de Sólon a Creso] e outros; posteriormente, designa uma pessoa de elevado caráter moral e espírito cívico; quanto às inscrições, veja, por exemplo, o índice VIII de OGI) nobreza de caráter, excelência <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:10</a> v.l.; IEph 14:1.—JBerlage, De vi et usu vocum <span class=\"greek\">καλὸς κἀγαθός</span>, <span class=\"greek\">καλοκαγαθία</span>: Mnemosyne 60, ’33, 20–40; JJüthner, Rzach Festschr. 1930, 99–119; Danker, Benefactor 319f.—Larfeld I 497. DELG sob o verbete <span class=\"greek\">καλός</span>. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καλοποιέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">καλός</span> e <span class=\"greek\">ποιέω</span>; Etym. Mag. 189, 24; PLond IV, 1338, 28; Lev 5:4 variante textual segundo Swete; cf. Fílon, Somn. 2, 296 variante textual) fazer o que é correto, fazer o bem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:13</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καλός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(documentado desde Homero; relativo ao que satisfaz padrões elevados ou expectativas quanto à aparência, espécie ou qualidade) superlativo <span class=\"greek\">κάλλιστος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Diod S 5, 13, 1; JosAs 14:17 cod. A; ApcSed 11:4 p. 134, 14 Ja. <span class=\"greek\">καλλίστατε</span>; Jos., Ant. 16, 142; Just., D. 20, 3; Tat. 28, 1).</p><p class=\"entry-text\"> ① relativo ao que é atraente pela aparência exterior: belo, formoso, elegante, de boa aparência <span class=\"greek\">λίθοι κ</span>. pedras belas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:5</a>. Referente a pessoas: (Lucian, Tim. 16, Dial. Mort. 1, 3) Hv 3, 13, 1; Hs 9, 3, 1.</p><p class=\"entry-text\"> ② relativo ao que corresponde de modo excelente à finalidade de alguma coisa ou pessoa: bom, útil.</p><p class=\"entry-text\"> ⓐ referente a coisas: <span class=\"greek\">τόπον καλὸν ἀνακεχωρηκότα</span> um belo lugar afastado Hv 3, 1, 3; no sentido físico, sem defeitos, de boa qualidade, precioso, em oposição a <span class=\"greek\">σαπρός</span> (PLond II, 356, 4ff p. 252 [século I d.C.]; TestJob 7:5 <span class=\"greek\">ἄρτον</span> [em oposição a <span class=\"greek\">κεκαιμένον</span>]) referente a peixes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:48</a>; no superlativo, <span class=\"greek\">τὰ κάλλιστα</span>, os especialmente bons vs. 48 D. Referente a uma árvore e a seu fruto 12:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:43</a>. Em oposição a <span class=\"greek\">πονηρός</span>, referente a frutos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:17f</a>f. Em outros contextos, acerca de frutos (Menand., Mon. 303 Mei. [402 J.] <span class=\"greek\">καρπός</span>) 3:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:9</a>; Hs 2, 4. <span class=\"greek\">ἀμπελῶνες</span> m 10, 1, 5. <span class=\"greek\">τράγοι</span> B 7:6, 10. <span class=\"greek\">γῆ</span> solo bom <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:8</a>, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:8</a>, 20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:15</a>. <span class=\"greek\">σπέρμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:24</a>, 27, 37f. <span class=\"greek\">οἶνος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:10a</a>b; Hm 12, 5, 3. <span class=\"greek\">μαργαρῖται</span> pérolas de boa qualidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:45</a>. Substantivado: (Epict. 1, 12, 12 <span class=\"greek\">καλόν τι ἐλευθερία ἐστί</span>) <span class=\"greek\">καλὸν τὸ ἅλας</span> o sal é uma coisa boa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:34</a>. <span class=\"greek\">ἔργον</span> algo útil Hs 5, 2, 7.—No superlativo, acerca dos escritos de Policarpo <span class=\"greek\">συγγράμματα κάλλιστα</span> escritos excelentes EpilMosq 2.</p><p class=\"entry-text\"> ⓑ referente à qualidade moral (em oposição a <span class=\"greek\">αἰσχρός</span>, IAndrosIsis, Kyme 32): bom, nobre, louvável, que contribui para a salvação etc. <span class=\"greek\">ἔργον καλόν</span>, <span class=\"greek\">ἔργα καλά</span> (Hippocr., Ep. 27, 30; Athen. 1, 15 p. 8f <span class=\"greek\">ἐν τοῖς καλοῖς ἔργοις</span>; SibOr 3, 220) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:16</a>; 26:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:32f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:10</a>, 25; 6:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:7</a>, 14; 3:8ab, 14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:10</a> v.l.; 2 Cl 12:4. <span class=\"greek\">λόγια τοῦ θεοῦ</span> 2 Cl 13:3. <span class=\"greek\">καλόν</span>: <span class=\"greek\">ἐν καλῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:18b</a>; cf. Pol 6:3. (Em oposição a <span class=\"greek\">κακόν</span>) <span class=\"greek\">διάκρισις καλοῦ τε καὶ κακοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:14</a> (Sext. Emp., Pyrrh. 3, 168 <span class=\"greek\">διάκρισις τῶν τε καλῶν κ</span>. <span class=\"greek\">κακῶν</span>). (<span class=\"greek\">τὸ</span>) <span class=\"greek\">κ</span>. (em oposição a <span class=\"greek\">κακ</span>.) <span class=\"greek\">ποιεῖν</span> (2 Ch 14:1; 31:20) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:7</a>. Sem o contraste com <span class=\"greek\">κακ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:17</a>; 1 Cl 8:4 (Is 1:17); Dg 4:3. <span class=\"greek\">κατεργάζεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:18</a>. <span class=\"greek\">ἐργάζεσθαι</span> B 21:2. <span class=\"greek\">καλὰ προνοεῖσθαι ἐνώπιόν τινος</span> (Pr 3:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:17</a>; semelhantemente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:21</a>.—<span class=\"greek\">ἀναστροφή</span> (cf. 2 Macc 6:23) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:12</a>. <span class=\"greek\">συνείδησις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:18</a> (cf. PRein 52, 5 <span class=\"greek\">οὐ καλῷ συνειδότι χρώμενοι</span>); <span class=\"greek\">φόβος</span> 1 Cl 21:8; <span class=\"greek\">νουθέτησις</span> 56:2; <span class=\"greek\">νηστεία</span> Hs 5, 3, 5; <span class=\"greek\">μαρτυρία κ</span>. boa reputação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:7</a>. <span class=\"greek\">ἐν καρδίᾳ καλῇ κ</span>. <span class=\"greek\">ἀγαθῇ</span> em coração nobre e bom <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:15</a> (com <span class=\"greek\">ἀγ</span>., como frequentemente nos escritos greco-romanos para caracterizar cidadãos exemplares [veja <span class=\"greek\">καλοκἀγαθία</span>], também em Josefo, Ant. 4, 67; 10, 188 al.; Just., A II, 2, 7 al.). Referente à lei, moralmente irrepreensível (Maximus Tyr. 20, 9a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:16</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:8</a>. <span class=\"greek\">ἐντολαί</span> Hm 12, 3, 4; Hs 6, 1, 1f. <span class=\"greek\">οὐ καλὸν τὸ καύχημα ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:6</a>. <span class=\"greek\">τοῦτο καλὸν καὶ ἀπόδεκτον ἐνώπιον τ</span>. <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:3</a>; 5:4 v.l.; cf. 1 Cl 7:3; 21:1; 60:2; 61:2; Pol 6:1 (Pr 3:4). <span class=\"greek\">πολυτέλεια καλὴ καὶ ἱλαρά</span> Hs 1, 10. <span class=\"greek\">λειτουργία</span> 5, 3, 8. No superlativo, referente aos mártires <span class=\"greek\">ὑπόδειγμα κάλλιστον</span> exemplo excelente 1 Cl 6:1.</p><p class=\"entry-text\"> ⓒ irrepreensível sob qualquer aspecto: sem culpa, excelente.</p><p class=\"entry-text\"> <span class=\"greek\">α</span>. referente a pessoas: <span class=\"greek\">κύριος</span> B 7:1; cf. 19:11 (<span class=\"greek\">καλό</span>, referente a Deus: Celsus 4, 14). <span class=\"greek\">μαθητής</span> IPol 2:1. <span class=\"greek\">ἱερεῖς</span> IPhld 9:1. <span class=\"greek\">διάκονος Χριστοῦ Ἰ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:6a</a>. <span class=\"greek\">οἰκονόμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:10</a>. <span class=\"greek\">στρατιώτης Χρ</span>. <span class=\"greek\">Ἰ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:3</a>. <span class=\"greek\">ποιμήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:11a</a>b, 14. <span class=\"greek\">ἀνταποδότης</span> D 4:7.</p><p class=\"entry-text\"> <span class=\"greek\">β</span>. referente a coisas: <span class=\"greek\">μέτρον</span> medida boa, cheia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:38</a>. <span class=\"greek\">θεμέλιος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:19</a>. <span class=\"greek\">βαθμός</span> 3:13. <span class=\"greek\">ἔργον</span> algo proveitoso, benéfico 3:1. <span class=\"greek\">διδασκαλία</span> 4:6b. <span class=\"greek\">παραθήκη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:14</a>. <span class=\"greek\">ὁμολογία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:12b</a>, 13. <span class=\"greek\">ἀγών</span> 6:12a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:7</a>. <span class=\"greek\">στρατεία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:18</a>. <span class=\"greek\">κτίσμα</span> (3 Macc 5:11) 4:4. <span class=\"greek\">πλάσμα</span> B 6:12. <span class=\"greek\">σκεῦος</span> 21:8. <span class=\"greek\">βάπτισμα</span> ApcPt Rainer 4. <span class=\"greek\">καλὸν θεοῦ ῥῆμα</span> (cf. Josh 21:45; 23:15; Zech 1:13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:5</a>. <span class=\"greek\">τὸ καλὸν ὄνομα τὸ ἐπικληθὲν ἐφ</span>’ <span class=\"greek\">ὑμᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:7</a> (num grafito pompeiano [Dssm., LO 237; LAE 277] um amante fala do <span class=\"greek\">καλὸν ὄνομα</span> de sua amada). <span class=\"greek\">οὐδὲν φαινόμενον καλόν</span> (<span class=\"greek\">ἐστιν</span>) IRo 3:3. <span class=\"greek\">πάντα ὁμοῦ κ</span>. <span class=\"greek\">ἐστιν</span> IPhld 9:2. <span class=\"greek\">τὸ καλόν</span> aquilo que resiste à prova <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:21</a>.</p><p class=\"entry-text\"> ⓓ A expressão <span class=\"greek\">καλόν</span> (<span class=\"greek\">ἐστιν</span>), no sentido geral «é bom», qualifica coisas compreendidas em uma das classificações precedentes (Pr 17:26.—כָּלָן=<span class=\"greek\">καλόν</span>, empréstimo lexical na literatura rabínica).</p><p class=\"entry-text\"> <span class=\"greek\">α</span>. é agradável, desejável, vantajoso (Jos., Bell. 4, 163) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:4</a>; 18:8f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:33</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:26a</a>.</p><p class=\"entry-text\"> <span class=\"greek\">β</span>. é moralmente bom, agradável a Deus, favorável à salvação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:1</a> (cf. Gen 2:18), 8, 26b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:9</a>.—<span class=\"greek\">οὐ καλόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:27</a>.</p><p class=\"entry-text\"> <span class=\"greek\">γ</span>. <span class=\"greek\">καλόν ἐστιν αὐτῷ μᾶλλον</span> é melhor para ele <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:42</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:15</a>. <span class=\"greek\">καλόν</span> (<span class=\"greek\">σοί</span>) <span class=\"greek\">ἐστιν</span> … <span class=\"greek\">ἤ</span> é (mais) vantajoso (para ti) … do que (cf. Jon 4:3; ApcEsdr 1:6 p. 24, 13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:8f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:43</a>, 45, 47 (veja B-D-F §190, 2). <span class=\"greek\">καλὸν ἦν αὐτῷ</span> teria sido melhor para ele <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:21</a> v.l. (B-D-F §358, 1; 360, 1). Sem cópula <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:21</a>; 1 Cl 51:3; IRo 6:1; 2 Cl 16:4.—Aquilo que é bom ou melhor é expresso por um infinitivo que constitui o sujeito de <span class=\"greek\">καλόν ἐστιν</span> (Appian, Bell. Civ. 3, 13 §46 <span class=\"greek\">καλὸν εἴη τινὶ θνῄσκειν</span>; Polyaenus 8, 9, 2; Jos., Bell. 1, 650; 4, 163) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:26</a>; 18:8f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:18a</a>; Hm 6, 2, 9; também o infinitivo articular (Menand., Monost. 283; 291 [396; 410 J.] <span class=\"greek\">καλὸν τὸ θνῄσκειν</span> al.). <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ μὴ φαγεῖν κρέα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:26b</a>; IEph 15:1; IRo 2:2; Pol 5:3; MPol 11:1; com acusativo e infinitivo <span class=\"greek\">ἡμᾶς ὧδε εἶναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:33</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:43</a>, 45, 47; B 21:1; com <span class=\"greek\">εἰ</span> (ApcSed 4:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:24</a> (1Cl 46:8); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:42</a>; 14:21; com <span class=\"greek\">ἐάν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:8</a>. Veja B-D-F §409, 3; KBeyer, Semitische Syntax im NT ’62, 76–78.—B. 1176; 1191. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάλπις, ιδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e outros; 4 Macc 3:12 variante textual) jarro GJs 11:1 (duas vezes).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάλυμμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja o artigo seguinte; Homero e outros; inscrição de Delos [século III a.C.]: BCH 32, 13, nº 3a, 42; LXX; Philo, Leg. All. 2, 53; TestJud 14:5) cobertura para a cabeça, véu, literalmente, referindo-se ao véu com que Moisés cobriu o rosto (Ex 34:33–35) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:13</a>.—<span class=\"greek\">κ</span>. é variante textual de <span class=\"greek\">ἐξουσία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:10</a>.—Figuradamente: véu, cobertura que impede a compreensão correta <span class=\"greek\">τὸ αὐτὸ κ</span>. <span class=\"greek\">ἐπὶ τῇ ἀναγνώσει</span> … <span class=\"greek\">μένει</span> o mesmo véu permanece quando … é lido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:14</a> (JCarmignac, NTS 24, ’77/78, 384–86). <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπὶ τὴν καρδίαν κεῖται</span> um véu está sobre a mente vs. 15; <span class=\"greek\">περιαιρεῖται τὸ κ</span>. a cobertura é retirada vs. 16 (cf. Ex 34:34).—JGöttsberger, D. Hülle des Mos. nach Ex 34 u. 2 Cor 3: BZ 16, 1924, 1–17; SSchulz, Die Decke des Moses (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:7</a>–18): ZNW 49, ’58, 1–30; CHickling, The Sequence of Thought in 2 Cor 3: NTS 21, ’74/75, 380–95.—B. 436. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καλύπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro <span class=\"greek\">καλύψω</span>; 1º aoristo <span class=\"greek\">ἐκάλυψα</span>; perfeito, 3ª pessoa do singular <span class=\"greek\">κεκάλυφεν</span> Num 22:11. Na voz passiva: futuro, 3ª pessoa do singular <span class=\"greek\">καλυφθήσεται</span> Eccl 6:4; particípio perfeito <span class=\"greek\">κεκαλυμμένος</span> (veja o artigo precedente; em Homero, Píndaro e nos trágicos; raro na prosa ática [X., Cyr. 5, 1, 4 <span class=\"greek\">κεκαλυμμένη</span>, Equ. 12, 5]; mas com frequência crescente em Aristóteles, Plutarco, Pausânias e Élio Aristides [Anz 271], também em inscrições; CPR 239, 5; LXX; pseudoepígrafos; Philo, Leg. All. 3, 158; Jos., Ant. 13, 208; SibOr 4, 53. Provavelmente passou do jônico para o grego coiné [Nägeli 27]); em sentido geral, «cobrir, esconder, ocultar».</p><p class=\"entry-text\"> ① fazer com que algo ou alguém seja coberto fisicamente, cobrir alguém, literalmente <span class=\"greek\">τινά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:30</a>, talvez no sentido especial de «sepultar» (exemplos em HGüntert, Kalypso 1919, 31ff; também inscrição em CB I/2, 476 no. 342). <span class=\"greek\">τί τινι</span> cobrir algo com alguma coisa (Num 4:12) <span class=\"greek\">λύχνον σκεύει κ</span>. uma lâmpada com um recipiente 8:16 (cf. Num 4:9). Referindo-se a um barco <span class=\"greek\">καλύπτεσθαι ὑπὸ τῶν κυμάτων</span> ser coberto pelas ondas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:24</a> (Achilles Tat. 3, 2, 6; Ps 77:53; Ex 15:10).</p><p class=\"entry-text\"> ② fazer com que algo não seja conhecido; esconder, ocultar, manter em segredo</p><p class=\"entry-text\"> ⓐ encobrir, retirar da vista <span class=\"greek\">πλῆθος ἁμαρτιῶν</span> (cf. Ps 84:3; ApcSed 1:2; veja também Philosoph. Max. p. 490, 56 <span class=\"greek\">ἡ εὔνοια τὴν ἁμαρτίαν περιστέλλει</span>; cf. Pind., N. 5, 16–18) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:20</a>; 1 Cl 49:5; 2 Cl 16:4 (quanto aos 4 últimos exemplos, cf. também Prov 10:12). <span class=\"greek\">ἁμαρτίας</span> Dg 9:3.</p><p class=\"entry-text\"> ⓑ ocultar (Os 10:8); no perfeito passivo, «estar encoberto» (=não conhecido), a respeito do evangelho: <span class=\"greek\">κεκαλυμμένον τὸ εὐαγγέλιον ἡμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:3</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:26</a> (Vi. Aesopi W 110 p. 102, 17 P. <span class=\"greek\">πάντα τὰ καλυπτόμενα ὁ χρόνος εἰς φῶς ἄγει</span>).</p><p class=\"entry-text\"> ⓒ véu sobre a <span class=\"greek\">καρδία</span> (veja esse verbete, 1b<span class=\"greek\">β</span>), referindo-se aos discípulos que não compreendiam: nosso coração não estava velado? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:32</a> D.—B. 849. DELG. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καλῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio de <span class=\"greek\">καλός</span> (documentado desde Homero; empréstimo na literatura rabínica; <span class=\"greek\">καλῶς</span> passa a suplantar <span class=\"greek\">εὖ</span>: JLee, NovT 27, ’85, 11–13.) em sentido geral, «bem, belamente».</p><p class=\"entry-text\"> ① relativo ao que satisfaz padrões relativamente elevados de excelência ou expectativa: adequadamente, apropriadamente, corretamente, esplendidamente (Is 23:16) <span class=\"greek\">κ</span>. <span class=\"greek\">πάντα πεποίηκεν</span> ele fez realmente tudo muito bem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:37</a>. <span class=\"greek\">διὰ τὸ κ</span>. <span class=\"greek\">οἰκοδομῆσθαι αὐτήν</span> porque fora bem construída <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:48</a>; <span class=\"greek\">καλῶς κτισθέντα</span> (em oposição a <span class=\"greek\">ἄχρηστα</span>) criado para um bom propósito Dg 4:2. <span class=\"greek\">σὺ κάθου ὧδε κ</span>. senta-te aqui num bom lugar = aqui está um lugar agradável para ti <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:3</a> (=<span class=\"greek\">ἐν καλῷ</span>, como em Alciphron, Ep.3, 20 <span class=\"greek\">ἄγει μέ τις λαβὼν εἰς τὸ θέατρον</span>, <span class=\"greek\">καθίσας ἐν καλῷ</span> «alguém me levou ao teatro e me indicou um bom assento»; Lucian, Paras. 50 <span class=\"greek\">καλῶς κατακείμενος</span>; outras passagens em Field, Notes 236), a menos que <span class=\"greek\">κ</span>. signifique aqui «por favor» (assim JRopes, ICC 1916, comentário ao trecho; NRSV. Ambas as traduções captam o tom respeitoso de <span class=\"greek\">κ</span>.). <span class=\"greek\">σὺ κ</span>. <span class=\"greek\">εὐχαριστεῖς</span> podes dar graças de modo suficientemente bom <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:17</a>; <span class=\"greek\">ἐτρέχετε κ</span>. corríeis tão bem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:7</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:4</a>, 12 (Diog. L. 1, 70 Quílon aconselha que se deve <span class=\"greek\">μανθάνειν τῆς αὑτοῦ οἰκίας καλῶς προστατεῖν</span>), 13; 5:17; Papias (4). Nessas passagens, a acepção aproxima-se da acepção 2.</p><p class=\"entry-text\"> ② relativo ao que satisfaz expectativas de excelência pessoal: de modo louvável, irrepreensivelmente <span class=\"greek\">ζηλοῦσιν οὐ καλῶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:17</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἀναστρέφεσθαι</span> (veja <span class=\"greek\">ἀναστρέφω</span> 3a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:18</a>. <span class=\"greek\">πολιτεύεσθαι</span> 1 Cl 44:6. <span class=\"greek\">κ</span>. <span class=\"greek\">καὶ ἁγνῶς</span> Hs 5, 6, 6; <span class=\"greek\">ἀγωνίζεσθαι</span> 2 Cl 7:1 (cf. 1 Tim 6:12). <span class=\"greek\">ἐργάζεσθαι</span> Hm 7, 1. <span class=\"greek\">δουλεύειν</span> Hs 5, 6, 5. <span class=\"greek\">κ</span>. <span class=\"greek\">καὶ δικαίως παραδεδόσθαι</span> 1 Cl 51:2. <span class=\"greek\">κ</span>. <span class=\"greek\">καὶ ἀληθῶς φρονεῖν</span> Hm 3, 4. <span class=\"greek\">κ</span>. <span class=\"greek\">καὶ σεμνῶς ὁρᾶν</span> Hs 9, 1, 2. <span class=\"greek\">τὸ κ</span>. <span class=\"greek\">ἔχον</span> conduta ordeira 1 Cl 14:2. <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχει θεὸν καὶ ἐπίσκοπον εἰδέναι</span> é louvável honrar a Deus e, ao mesmo tempo, ao dirigente (bispo) ISm 9:1.</p><p class=\"entry-text\"> ③ relativo ao que traz vantagem, de modo benéfico ou aceitável, bem <span class=\"greek\">κ</span>. <span class=\"greek\">ποιεῖν</span> fazer o bem (Lucian, Ep. Sat. 3, 31) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:12</a>. Com dativo (Zeph 3:20) <span class=\"greek\">τοῖς μισοῦσιν ὑμᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:44</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:27</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">λέγειν</span> com acusativo: falar bem de 6:26. Veja B-D-F §151, 1. <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχειν</span> estar bem, ter boa saúde <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:18</a> (<span class=\"greek\">ἔχω</span> 10b). <span class=\"greek\">καλῶς λαμβάνειν</span> receber hospitaleiramente Hs 9, 11, 8 (<span class=\"greek\">λαμβάνω</span> 5).</p><p class=\"entry-text\"> ④ relativo ao que está conforme a uma norma: corretamente, com acerto</p><p class=\"entry-text\"> ⓐ <span class=\"greek\">κ</span>. <span class=\"greek\">ποιεῖν</span> fazer o que é correto, agir com acerto, agir bem (Dio Chrys. 30 [47], 25; Ael. Aristid. 36 p. 685 D.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:37f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:8</a>, 19; Hv 2, 4, 2. Com particípio (Appian, Bell. Civ. 3, 75 §305; Sb 5216, 7 [I b.c.]; 6265, 8 [I a.d.]; POslo 55, 7; Jos., Ant. 11, 279; B-D-F §414, 5; Rob. 1121) ter a bondade de fazer alguma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:14</a>; agir bem ao fazer alguma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:19</a>; 3J 6; GEg 252, 53; ISm 10:1</p><p class=\"entry-text\"> ⓑ com verbos de falar, ouvir e compreender <span class=\"greek\">κ</span>. <span class=\"greek\">ἀποκρίνεσθαι</span> responder corretamente, bem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:28</a>. <span class=\"greek\">εἰπεῖν</span> (Simplício, comentário a Epicteto p. 44, 50; 47, 51; Jos., Ant, 8, 380) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:17</a>; B 10:11; AcPl Ha 1, 25. <span class=\"greek\">λαλεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:25</a>. <span class=\"greek\">λέγειν</span> (TestJob 7:8; Epict. 1, 19, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.48\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:48</a>; 13:13; cf. 18:23. <span class=\"greek\">μανθάνειν</span>, <span class=\"greek\">μνημονεύειν</span> Papias (2:3). <span class=\"greek\">προφητεύειν</span> profetizar corretamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:6</a>; PEg2 54; cf. <span class=\"greek\">κ</span>. <span class=\"greek\">ἀκούειν</span> ouvir corretamente (Menand., Fgm. 507 Kö.) Hm 4, 3, 2. <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπίστασθαί τι</span> conhecer bem alguma coisa 1 Cl 53:1 (Appian, Bell. Civ. 2, 98 §406 <span class=\"greek\">εἰδέναι κ</span>.; Procop. Soph., Ep. 18 <span class=\"greek\">ἴσθι κ</span>.=podes ter plena certeza).</p><p class=\"entry-text\"> ⓒ em sentido geral <span class=\"greek\">μισεῖν</span> B 10:8; <span class=\"greek\">καταπαύεσθαι</span> 15:5, 7; <span class=\"greek\">ἀξιοῦν</span> Dg 3:2.—Como exclamação, <span class=\"greek\">καλῶς</span>: Muito bem! É verdade! Bem dito! (Arrian, Cyneg. 18, 1; Ael. Aristid. 33 p. 617 D.; 45 p. 44; Lucian, Dial. Deor. 20, 10; 3 Km 2:18) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:20</a>.</p><p class=\"entry-text\"> ⑤ felizmente, <span class=\"greek\">καλῶς ἐξέφυγες</span>, felizmente escapaste Hv 4, 2, 4.</p><p class=\"entry-text\"> ⑥ em sentido irônico (Soph., Ant. 739; Aelian, VH 1, 16 al.) <span class=\"greek\">κ</span>. <span class=\"greek\">ἀνέχεσθε</span> suportais isso muito bem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:4</a> (Moffatt; veja PKirberg, Die Toleranz der Korinther 1910; JMachen, The Origin of Paul’s Religion 1921, 131ff). <span class=\"greek\">κ</span>. <span class=\"greek\">ἀθετεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:9</a>. Entretanto, talvez aqui o <span class=\"greek\">καλῶς</span> do versículo 6, que não é irônico, exija interpretação semelhante; a frase deveria, então, ser interrogativa: procedeis corretamente ao rejeitar o mandamento de Deus?</p><p class=\"entry-text\"> ⑦ comparativo <span class=\"greek\">κάλλιον</span> (com valor de superlativo, como em Galeno, Protr. 8 p. 24, 19 J.=p. 10, 31 Kaibel; veja B-D-F §244, 2) <span class=\"greek\">ὡς καὶ σὺ κ</span>. <span class=\"greek\">ἐπιγινώσκεις</span> como tu também sabes muito bem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:10</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καμάρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Heródoto e outros; Diod S 3, 19, 2; 17, 82, 3; SIG 1243, 4; papiros) arco, abóbada, recinto abobadado (Is 40:22) MPol 15:2 (quanto às acepções da palavra cária da qual se afirma que deriva, veja FSolmsen, BPhW 26, 1906, 853; cf. a observação cautelosa de Boisacq 402).—DELG e Frisk.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κἀμέ</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">veja <span class=\"greek\">κἀγώ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάμηλος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino e feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">e <span class=\"greek\">ἡ</span> (de origem semítica, cf. o hebraico גָּמָל; Aeschyl., Hdt.; inscrições e papiros, LXX, TestSol, TestJob, Philo; Jos., Ant. 1, 252; 8, 167 e outros; Ath., R. 12 p. 61, 11) camelo; <span class=\"greek\">τρίχες καμήλου</span>, pelo de camelo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:6</a>; GEb 13, 79 (aqui, naturalmente, não se trata do macio <span class=\"greek\">τρίχες καμήλου</span> com o qual, segundo Ctésias, se confeccionam as vestes de pessoas ilustres [século IV a.C.]: 688 Fgm. 10 Jac.). Em expressão proverbial, <span class=\"greek\">εὐκοπώτερόν ἐστιν κάμηλον διὰ τρυπήματος</span> [vv.ll. <span class=\"greek\">τρήματος</span>, <span class=\"greek\">τρυμαλίας</span>] <span class=\"greek\">ῥαφίδος διελθεῖν</span> é mais fácil um camelo passar pelo fundo de uma agulha representação de algo impossível, com contraste fortemente acentuado, talvez também com efeito humorístico em razão da corcova (quanto a um provérbio que compara algo muito pequeno a algo muito grande, cf. Lucian, Ep. Sat. 1, 19 <span class=\"greek\">μύρμηξ ἢ κάμηλος</span>): o maior animal e a menor abertura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:24</a>; com variações <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:25</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:25</a> (veja <span class=\"greek\">κάμιλος</span>; GAicher, Kamel u. Nadelöhr 1908; ERostan, Les Paradoxes de Jésus 1908, 11ff; WBleibtreu [veja <span class=\"greek\">μισέω</span> 2] 17f; RLehmann u. KLSchmidt, ThBl 11, ’32, 336–40; EBöklen, Deutsches Pfarrerblatt 37, ’33, 162–65; CLattey, Verb. Dom. 31, ’53, 291f; EBest, ET 82, ’70, 83–89; JDerrett, NTS 32, ’86, 465–70). Coar um mosquito <span class=\"greek\">τὴν δὲ κ</span>. <span class=\"greek\">καταπίνειν</span> mas engolir um camelo = ser excessivamente rigoroso nas coisas pequenas e descuidado nas importantes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:24</a> (veja <span class=\"greek\">κώνωψ</span>.—O camelo é contraposto ao elefante em Fálaris, Ep. 86; Ps.-Libanius, Ep. 1597, 1 ed. F. XI p. 593, 1.—Artem. 4 p. 199, 9 explica que camelo e elefante teriam a mesma acepção numa interpretação figurada).—JSauer, in Studies in the History and Archeology of Jordan V ’95, 39–48.—BHHW II 923; Pauly-W. X 2, 1824–32; B. 189f. OEANE I 406–8. EDNT. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάμιλος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">corda, cabo de navio, é a leitura de diversos manuscritos e de diversas versões (por exemplo, a armênia; FHerklotz, BZ 2, 1904, 176f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:25</a> em lugar de <span class=\"greek\">κάμηλος</span> (veja esse verbete). <span class=\"greek\">κάμιλος</span>, documentada apenas na Suda 1967c e nos escólios sobre Aristófanes (Vesp. 1035), pode ser antiga (B-D-F §24; Mlt-H. 72—«invenção bizantina»), mas constitui leitura secundária nos Evangelhos.—Boisacq 403, nota 1; Bröndal, BPhW 38, 1918, 1081f; PHaupt, Camel e Cable: AJP 45, 1924, 238ff.—DELG. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάμινος, ου, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ésquilo, Heródoto e outros; IG IV, 332; papiros, LXX, TestSol 11:7; ParJer 6:23 [figuradamente, com referência ao Egito]; Joseph., empréstimo lexical na literatura rabínica Veja Schwyzer II 34 n. 2; B-D-F §49, 1) forno, fornalha <span class=\"greek\">καπνὸς καμίνου</span> (Ex 19:18; Job 41:12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:2</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ πυρός</span> forno ardente, fornalha (Da 3:6, 11 al.) referente a fornos de ceramistas (Sir 27:5) 2 Cl 8:2. Referente a fornalhas de fundição (X., Vectig. 4, 49; Diod S 5, 13, 1; 5, 27, 2; Ezk 22:20, 22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:15</a>; MPol 15:2. <span class=\"greek\">κ</span>. <span class=\"greek\">πυρός</span> como local da prova de fogo dos três jovens (Da 3:20ff; 4 Macc 16:21; Jos., Ant. 10, 213) 1 Cl 45:7. AcPl Ha 6, 20 numa imagem referente a Roma. Figuradamente, referindo-se ao inferno <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:42</a>, 50.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καμμύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro <span class=\"greek\">καμμύσω</span> (LXX; TestJob 40:4); 1º aoristo <span class=\"greek\">ἐκάμμυσα</span> (forma contraída de <span class=\"greek\">καταμύω</span>; censurada por Frínico 339f Lob., difundiu-se a partir dos poetas [Batr. 191; Alexis Com. 319; Apollon. Dysc., Synt. 323, 22; 326, 9] na linguagem popular: X., Cyr. 8, 3, 27 codd.; Hero Alex. I p. 412, 5; PGM 4, 586; 958; 1057; 1069; 7, 855; 13, 945; LXX [Thackeray 99]; Philo [s. below].—W-S. §5, 22c; 12, 6; B-D-F §69, 1; Mlt-H. 92; 243; 398; Thumb 63f; Crönert 64, 4) fechar (os olhos) <span class=\"greek\">τοὺς ὀφθαλμούς</span> (assim em Pseudo-Calístenes 3, 33, 27 com referência a Alexandre moribundo) figuradamente (Fílon, Somn. 1, 164 <span class=\"greek\">καμμύσαντες τὸ τ</span>. <span class=\"greek\">ψυχῆς ὄμμα</span>; La 3:45) referente a uma atitude de hostilidade para com o evangelho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:27</a> (ambas as passagens citam Is 6:10).—DELG sob o verbete <span class=\"greek\">μύω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάμνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">2º aoristo <span class=\"greek\">ἔκαμον</span>; perfeito <span class=\"greek\">κέκμηκα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:3</a> texto recebido (veja o aparato de Tischendorf), particípio <span class=\"greek\">κεκμηκώς</span>; futuro, 2ª pessoa do singular, voz média <span class=\"greek\">καμῇ</span> (ApcMos 24).</p><p class=\"entry-text\"> ① estar cansado, fatigado (assim em Homero e outros; PGiss 47, 8; PLond V, 1708, 50; 4 Macc 3:8; TestIss 3:6; JosAs 11 cod. A [p. 53, 8 Bat.] e Pal. 364; ApcMos) <span class=\"greek\">τῇ ψυχῇ</span> no espírito Hm 8:10. Aqui se pode pensar num cansaço da alma (quanto a cansaço desse tipo, cf. Diod S 20, 96, 3 <span class=\"greek\">κάμνοντες ταῖς ψυχαῖς</span>; Philo, Post. Cai. 31 [a alma errante]; Jos., Ant. 2, 290; Just., D. 5, 6). Entretanto, outra interpretação talvez possa ser deduzida de Diod S 15, 38, 2: <span class=\"greek\">κάμνειν τῇ συνεχείᾳ τῶν πολέμων</span>=estar cansado ou fatigado pela sucessão contínua de guerras. Nesse caso, <span class=\"greek\">κάμνοντες τῇ ψυχῇ</span> não seriam os cansados no espírito, mas aqueles que estão cansados de viver (como Job 10:1).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:3</a> pode ser uso absoluto (como Jos., Vi. 209), isto é, se <span class=\"greek\">τ</span>. <span class=\"greek\">ψυχαῖς ὑμῶν</span> se liga a <span class=\"greek\">ἐκλυόμενοι</span>. <span class=\"greek\">ἔκαμνον ἐκ τῆς ὁδοῦ</span> fiquei cansado da viagem GJs 15:1. Referente a documentos <span class=\"greek\">σχεδὸν ἐκ τοῦ χρόνου κεκμηκότα</span> quase desgastados pelo tempo MPol 22:3; EpilMosq 5 (Diog. L. 9, 113: na casa de Timão, as obras dos poetas jazem desprotegidas, muitas delas parcialmente comidas [<span class=\"greek\">ἡμίβρωτα</span>]). Cansado pelo trabalho (TestJob 39:11 <span class=\"greek\">μή κάμητε εἰκῇ</span>; ApcMos 24) <span class=\"greek\">κεκοπίακας καί οὐ κέκμηκας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:3</a>, uma leitura de Erasmo (veja acima).</p><p class=\"entry-text\"> ② estar enfermo (assim em Sófocles, Heródoto e outros) <span class=\"greek\">ὁ κάμνων</span> o homem enfermo (Strabo 8, 6, 15; Musonius 20, 8 <span class=\"greek\">θεραπείαν τῶν καμνόντων</span>; Epict., Fgm. 19; M. Ant. 6, 55; SIG 943, 9f <span class=\"greek\">ἐπιμέλεια τῶν καμνόντων</span>; TestSol 18, 34 P; Philo, Omn. Prob. Lib. 12, Migr. Abr. 124 <span class=\"greek\">τὴν τῶν καμνόντων σωτηρίαν</span>; Tat.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:15</a>. Outra possibilidade aqui é a acepção «estar irremediavelmente enfermo, definhar» (escólio sobre Apollon. Rhod. 4, 1091 p. 306, 23 W.; Jos., Ant. 8, 266), ou até</p><p class=\"entry-text\"> ③ morrer (Crinagoras, no. 25, 1; Diod S 14, 71, 1 e 4; Dionys. Byz. §109; 110; Kaibel 321, 8 <span class=\"greek\">καμών</span>=morto; inscrições funerárias [ANock, Sallust. p. xxxiii, 94 <span class=\"greek\">ὅταν κάμῃς</span>, <span class=\"greek\">τοῦτο τὸ τέλος</span>=quando morreres, esse será o fim]; Wsd 4:16; 15:9; SibOr 3, 588).—B. 540. DELG. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κἀμοί</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">veja <span class=\"greek\">κἀγώ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καμπανός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo gentílico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">campano, pertencente à região da Campânia, no centro-sul da Itália (incluindo Nápoles e Cumas) <span class=\"greek\">ἡ ὁδὸς ἡ Κ</span>.=Via Campana, estrada da Campânia (CIL VI 2107, 3; 14; 10250; 29772) Hv 4, 1, 2.—MDibelius, manual, comentário ao trecho</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάμπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro <span class=\"greek\">κάμψω</span>; 1º aoristo <span class=\"greek\">ἔκαμψα</span>; aoristo passivo, 3ª pessoa do plural <span class=\"greek\">ἐκάμφθησαν</span> Job 9:13, infinitivo <span class=\"greek\">καμφθῆναι</span> 4 Macc 3:4. (Homero e outros; papiros, LXX, Fílon).</p><p class=\"entry-text\"> ① transitivamente, dobrar ou inclinar alguma parte do corpo, curvar-se, inclinar-se, frequentemente como gesto de respeito ou devoção: <span class=\"greek\">τὸν τράχηλον</span> o pescoço (Aesop, Fab. 452 p. 501, 12f P. <span class=\"greek\">ἔκαμψα τὸν ἐμαυτοῦ τράχηλον</span>) B 3:2 (Is 58:5). <span class=\"greek\">γόνυ</span> (também no plural) dobrar o joelho como sinal de devoção (religiosa) (LXX) <span class=\"greek\">τινί</span> diante de alguém (SibOr 3, 616f) <span class=\"greek\">τῇ Βάαλ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:4</a> (3 Km 19:18). Também <span class=\"greek\">πρός τινα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:14</a>. Figuradamente: <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ γόνατα τῆς καρδίας</span> (veja <span class=\"greek\">γόνυ</span>) 1 Cl 57:1.</p><p class=\"entry-text\"> ② intransitivamente (Polyaenus 3, 4, 3 <span class=\"greek\">ἔκαμψεν</span>=curvou-se para dentro) assumir postura curvada, dobrar-se <span class=\"greek\">ἐμοὶ κάμψει πᾶν γόνυ</span> todo joelho se dobrará diante de mim <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:11</a> (Is 45:23). <span class=\"greek\">ἐν τῷ ὀνόματι Ἰησοῦ</span> quando o nome de Jesus for proclamado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:10</a> (também influenciado por Is 45:23).—B. 542. Renehan ’75, 115f. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0185-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κἄν</h1><div class=\"entry-meta\"><span>partícula condicional</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(formado por crase de <span class=\"greek\">καὶ ἐάν</span>, documentável desde Hesíodo e outros; papiros, LXX [Thackeray 138]; TestAbr; TestJob; TestReub; TestJud; Philo, Aet. M. 134 e outros; Joseph.; SibOr 3, 18; Just., Tat., Ath.; W-S. §5, 8; B-D-F §18; 371; Rob. 208; com variações nos manuscritos) partícula geralmente acompanhada de subjuntivo (com indicativo Hs 5, 5, 4; Just. A I, 11, 2).</p><p class=\"entry-text\"> ① e se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:23</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:34</a> D; 13:9 (aqui, omite-se a primeira apódose [<span class=\"greek\">καλῶς ἔχει</span>], como é bastante frequente no ático; B-D-F §454, 4; veja Rob. 1023); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.55\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:55</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:15</a>; <span class=\"greek\">κἂν λίαν συνετὸς ἦν τις</span> Hs 5, 5, 4; <span class=\"greek\">κἂν μιάνῃς</span> 5, 7, 2. <span class=\"greek\">κἂν</span> … <span class=\"greek\">δέ</span> mas se IRo 5:2. <span class=\"greek\">κἂν</span> … <span class=\"greek\">κἂν</span> … <span class=\"greek\">κἂν</span> e se … e se … e se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:2f</a> v.l. <span class=\"greek\">κἂν</span> … <span class=\"greek\">κἂν</span> e se … e se, quer … quer (Demosth. 25, 15; TestJud 15:5, TestReub 4:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:38</a>.</p><p class=\"entry-text\"> ② mesmo se, ainda que <span class=\"greek\">οὐ μόνον</span> … <span class=\"greek\">ἀλλὰ κἂν εἴπητε</span> não apenas … mas mesmo se disserdes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:21</a>.—26:35 (<span class=\"greek\">κἂν δέῃ ἀποθανεῖν</span> como em Jos., Ant. 6, 108; 11, 228); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:14</a>; 10:38; 11:25; 2 Cl 19:3; mesmo que … apenas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:20</a>.</p><p class=\"entry-text\"> ③ ainda que apenas, pelo menos (Soph., El. 1483; Lucian, Tim. 20 <span class=\"greek\">κἂν ὄνος</span> «pelo menos um jumento»; PRein 52, 6; POxy 1593, 5ff <span class=\"greek\">κἂν νῦν</span> «pelo menos agora»; <span class=\"greek\">κἂν τοσοῦτον</span> pelo menos tanto Ath. 20, 3) <span class=\"greek\">κἂν τῶν ἱματίων</span> apenas suas roupas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:28</a>; cf. 6:56 (cf. TestJob 12:1 <span class=\"greek\">κἂν διακονῆσαι</span> … <span class=\"greek\">σήμερον</span>; Athen. 5, 212f <span class=\"greek\">ἑκάστου σπεύδοντος κἂν προσάψασθαι τῆς ἐσθῆτος</span>). <span class=\"greek\">κἂν ἡ σκιά</span> pelo menos sua sombra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:15</a>. <span class=\"greek\">κἂν ὡς ἄφρονα δέξασθέ με</span> recebei-me ao menos como insensato <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:16</a>.—2 Cl 18:2; IEph 10:1. Na apódose de uma frase condicional 2 Cl 7:3; GPt 12:52, 54.—<span class=\"greek\">κἂν ταῦτα</span> mesmo que seja isto, por pouco que seja Dg 2:10 (cf. Luciano, Dial. Mar. 1, 3).—M-M.</p></section></article>\n"};
